/* ============================================================
   quiz-banks-ext.js — deepened question banks (5 more per module)
   Appended to AV.data.quizBanks after quiz-banks.js loads, taking
   each module from 3 to 8 questions. Some questions carry a `code`
   snippet (predict-the-output style) rendered above the prompt.
   diff: beginner | intermediate | advanced | senior
   ============================================================ */
(function () {
  "use strict";
  var AV = (window.AirflowViz = window.AirflowViz || {});
  var B = (AV.data && AV.data.quizBanks) || (AV.data.quizBanks = {});
  function add(id, qs) { B[id] = (B[id] || []).concat(qs); }

  add("fundamentals", [
    { q: "What does it mean that an API is a 'contract'?", options: ["The server and client agree on fixed hardware", "Both sides rely on an agreed request/response shape and behavior, so internals can change freely", "It is a legal document signed by both companies", "The client owns the server's database"], answer: 1, diff: "beginner", why: "A contract decouples caller from implementation: as long as the shape and semantics hold, the server can change its internals without breaking clients." },
    { q: "Why is an API usually preferred over giving partners direct database access?", options: ["Databases are slower than HTTP", "The API enforces validation, authorization and business rules, and hides schema changes", "Partners can't understand SQL", "It avoids needing a network"], answer: 1, diff: "intermediate", why: "Direct DB access leaks your schema and bypasses all your rules; an API is the control point for validation, authz, and a stable contract." },
    { q: "A ShopSphere order's final price should be determined by…", options: ["Whatever the client sends in `total`", "The server, recomputing from validated items and current pricing", "The customer's browser", "The CDN"], answer: 1, diff: "beginner", why: "Never trust a client-sent price — a malicious client would send $0. The server is the source of truth for money." },
    { q: "Which best describes idempotency at the API level?", options: ["The API never changes state", "Repeating the same request has the same effect as doing it once", "Every request returns the same body", "The API is stateless"], answer: 1, diff: "intermediate", why: "Idempotency is about the resulting state after repeats — crucial for safe retries, not about identical responses." },
    { q: "An internal, a partner, and a public API mainly differ in…", options: ["The programming language", "Who may call them and under what trust/contract (credentials, quotas, exposure)", "Whether they use JSON", "The HTTP version"], answer: 1, diff: "advanced", why: "The technical shape can be identical; what differs is the trust boundary — scoped credentials, quotas, and how much you expose." }
  ]);

  add("http-lab", [
    { code: "GET /v1/orders/ORD-10025 HTTP/1.1\nHost: api.shopsphere.example\nAuthorization: Bearer <token>\nAccept: application/json", q: "Which part of this request tells the server what representation the client wants back?", options: ["The Host header", "The Authorization header", "The Accept header", "The path"], answer: 2, diff: "beginner", why: "Accept drives content negotiation — the client states which media type(s) it can handle; the server picks one." },
    { q: "On a brand-new HTTPS connection, roughly what order do these happen?", options: ["TLS handshake → DNS → TCP", "DNS → TCP handshake → TLS handshake → request", "Request → DNS → TLS", "TCP → request → DNS"], answer: 1, diff: "intermediate", why: "Resolve the name (DNS), open the socket (TCP), negotiate encryption (TLS), then send the request. Keep-alive reuses the open, negotiated connection." },
    { code: "POST /v1/orders  (connection drops before any response arrives)", q: "Why is this worse than receiving a 500?", options: ["It isn't — identical", "The outcome is unknown: the write may have succeeded, so a blind retry can duplicate it", "Network errors can't be logged", "It always means the server is down"], answer: 1, diff: "advanced", why: "No response = uncertain outcome. That uncertainty is exactly why idempotency keys exist for unsafe methods." },
    { q: "A response has status 304 Not Modified. What does the client do?", options: ["Show an error", "Reuse its cached copy — the resource hasn't changed", "Retry with a new token", "Follow a redirect"], answer: 1, diff: "intermediate", why: "304 answers a conditional request (If-None-Match/If-Modified-Since): nothing changed, so use the cache and save bandwidth." },
    { q: "Keep-alive (connection reuse) primarily saves…", options: ["Database time", "The per-request DNS + TCP + TLS setup cost", "Serialization time", "Authentication time"], answer: 1, diff: "beginner", why: "The handshake costs are paid once per connection; reusing it amortizes them across many requests." }
  ]);

  add("http-methods", [
    { q: "Which methods are considered 'safe' (no intended side effects)?", options: ["GET and HEAD", "POST and PUT", "DELETE and PATCH", "All of them"], answer: 0, diff: "beginner", why: "Safe methods don't change state; infrastructure (caches, prefetchers, crawlers) may repeat them freely." },
    { code: "PATCH /v1/orders/ORD-1\n{ \"op\": \"increment\", \"field\": \"quantity\", \"by\": 1 }", q: "Is this PATCH idempotent?", options: ["Yes, PATCH always is", "No — repeating it keeps incrementing quantity", "Only over HTTPS", "Only with an ETag"], answer: 1, diff: "advanced", why: "Idempotency depends on the operation: 'set status=PAID' is idempotent; 'increment by 1' is not." },
    { q: "To fully replace a resource you use PUT; the risk of a partial PUT body is…", options: ["It's faster", "Omitted fields get wiped because PUT replaces the whole resource", "PUT merges by default", "PUT can't carry a body"], answer: 1, diff: "intermediate", why: "PUT is full replacement. For partial updates use PATCH, or you'll null out fields you didn't send." },
    { q: "A second DELETE on an already-deleted order returns 404. Is DELETE still idempotent?", options: ["No, the status differs", "Yes — the end state (resource gone) is unchanged", "Only the first call counts", "Only with a key"], answer: 1, diff: "advanced", why: "Idempotency is about resulting state, not identical responses; the resource is gone either way." },
    { q: "Why should 'cancel order' not be a GET?", options: ["GET is too slow", "GET is safe — caches/prefetchers/retries may repeat it and cause unintended cancellations", "GET can't reach the server", "GET needs a body"], answer: 1, diff: "beginner", why: "State changes must use an unsafe method (POST/PATCH/DELETE); GET may be replayed by infrastructure." }
  ]);

  add("status-codes", [
    { q: "A request is well-formed JSON but references a product that doesn't exist. Best status?", options: ["400", "404", "422", "500"], answer: 2, diff: "intermediate", why: "The syntax is fine (not 400); the body is semantically invalid → 422 Unprocessable Content. 404 is for the addressed resource itself." },
    { code: "HTTP/1.1 201 Created\nLocation: /v1/orders/ORD-10025", q: "What does a 201 with a Location header communicate?", options: ["The request failed", "A resource was created; its URL is in Location", "The client must authenticate", "The resource moved permanently"], answer: 1, diff: "beginner", why: "201 Created signals successful creation; Location points at the new resource so the client can fetch it." },
    { q: "When is 409 Conflict the right code?", options: ["Invalid JSON", "The request conflicts with current state (e.g. a version/ownership or concurrency clash)", "Missing auth", "Server crash"], answer: 1, diff: "advanced", why: "409 signals a conflict with the resource's current state — e.g. a failed optimistic-lock update or a duplicate unique value." },
    { q: "A downstream database times out while serving a request. Most accurate status?", options: ["400", "404", "503 (or 504 if it's an upstream gateway timeout)", "200"], answer: 2, diff: "intermediate", why: "A dependency failing is a server-side 5xx: 503 Service Unavailable, or 504 when a gateway's upstream times out. The client's request was fine." },
    { q: "Why prefer 404 over 403 for an object the caller doesn't own?", options: ["404 is faster", "403 confirms the object exists, leaking information; 404 hides it", "They're identical", "404 is cacheable"], answer: 1, diff: "senior", why: "In BOLA/IDOR-sensitive cases, 403 tells an attacker 'this id exists but isn't yours' — 404 reveals nothing." }
  ]);

  add("json-lab", [
    { code: "{ \"id\": 1, \"tags\": [\"a\", \"b\",], }", q: "Why does this fail to parse as JSON?", options: ["Keys need single quotes", "Trailing commas (after \"b\" and after the array) are invalid in JSON", "Numbers must be strings", "Arrays aren't allowed"], answer: 1, diff: "beginner", why: "JSON forbids trailing commas (JavaScript allows them) — a very common source of 400s." },
    { q: "Which is valid JSON?", options: ["{ name: 'Ada' }", "{ \"name\": \"Ada\" }", "{ 'name': 'Ada' }", "{ name: \"Ada\", }"], answer: 1, diff: "beginner", why: "JSON requires double-quoted keys and string values, and no trailing commas." },
    { q: "A number like an order id of 9007199254740993 risks what in JSON across languages?", options: ["Nothing", "Precision loss when parsed as a 64-bit float (beyond 2^53)", "It becomes a string automatically", "It is rejected by all parsers"], answer: 1, diff: "senior", why: "JSON numbers are often parsed as IEEE-754 doubles; large integer ids can lose precision — represent such ids as strings." },
    { q: "What status should a server return for a malformed JSON request body?", options: ["200", "400 Bad Request", "422", "503"], answer: 1, diff: "beginner", why: "Malformed syntax is rejected with 400 before any business logic; 422 is for well-formed-but-invalid." },
    { q: "`Content-Type: application/json` on a request tells the server…", options: ["How to authenticate", "How to parse the body (as JSON)", "Which version to use", "Which cache to hit"], answer: 1, diff: "intermediate", why: "Content-Type describes the body being sent so the server parses it correctly; Accept describes what the client wants back." }
  ]);

  add("rest-resources", [
    { q: "Which is the most RESTful way to list a customer's orders?", options: ["GET /v1/getCustomerOrders?id=5", "GET /v1/customers/5/orders", "POST /v1/orders/forCustomer", "GET /v1/orders/customer/list/5"], answer: 1, diff: "beginner", why: "Nouns, plural collections, ownership expressed by one level of nesting; the method carries the verb." },
    { q: "How deep should you nest resources as a rule of thumb?", options: ["As deep as the data model", "About one level (e.g. /customers/{id}/orders); flatten beyond that", "Never nest", "Exactly three levels"], answer: 1, diff: "intermediate", why: "Deep nesting (/a/{}/b/{}/c/{}) gets unwieldy; past ~2 levels, prefer a top-level resource with a filter." },
    { q: "You need both 'a customer's orders' and 'all orders filtered by status'. Best design?", options: ["Two unrelated endpoints with verbs", "/customers/{id}/orders for ownership and /orders?status=PAID for filtering", "One endpoint doing everything via POST", "Nest status under customer"], answer: 1, diff: "advanced", why: "Ownership is expressed by nesting; cross-cutting filters are query params on the collection — different concerns, different shapes." },
    { q: "Returning a top-level JSON array (not an object) from a collection endpoint is risky because…", options: ["Arrays are slower", "You can't add metadata (pagination, etc.) later without a breaking change", "Arrays aren't valid JSON", "Clients can't parse arrays"], answer: 1, diff: "senior", why: "Wrapping in { data: [...], pagination: {...} } leaves room to evolve; a bare array has nowhere to add metadata compatibly." },
    { q: "Which status/response fits creating a sub-resource POST /v1/orders/{id}/refunds?", options: ["200 with the order", "201 with the created refund and its Location", "204 no content", "404"], answer: 1, diff: "intermediate", why: "Creating a refund sub-resource returns 201 with the new refund representation and a Location to it." }
  ]);

  add("endpoint-designer", [
    { q: "Which endpoint name is the cleanest REST design?", options: ["POST /v1/createOrder", "POST /v1/orders", "GET /v1/orders/new", "POST /v1/order/make"], answer: 1, diff: "beginner", why: "Plural noun collection + POST to create; no verbs in the path, no singular/action names." },
    { q: "Filtering, sorting and pagination on a collection belong in…", options: ["The request body of a GET", "Query parameters (?status=PAID&sort=-createdAt&limit=20)", "Path segments", "Custom headers only"], answer: 1, diff: "intermediate", why: "These are query concerns expressed as query params; GETs shouldn't rely on a body." },
    { q: "A good URL for 'search products' that may have many optional filters is…", options: ["POST /v1/products/search with a JSON body (acceptable when filters are complex)", "GET /v1/searchProducts", "GET /v1/products/search/all", "PATCH /v1/products"], answer: 0, diff: "advanced", why: "GET /v1/products?filters is ideal, but when the filter set is large/complex, a POST /products/search with a body is a pragmatic, widely-used compromise." },
    { q: "Which is a breaking change to an endpoint's contract?", options: ["Adding a new optional query parameter", "Adding a new optional response field", "Renaming an existing response field", "Adding a new endpoint"], answer: 2, diff: "intermediate", why: "Renaming a field breaks clients reading the old name; the others are additive and backward compatible." },
    { q: "Consistent plural resource names and lowercase paths matter because…", options: ["They're required by HTTP", "Predictability reduces client errors and cognitive load across the API", "They make responses smaller", "Uppercase breaks TLS"], answer: 1, diff: "beginner", why: "Consistency is a usability feature: a predictable API is easier to learn and harder to misuse." }
  ]);

  add("pagination", [
    { q: "Why does deep offset pagination (e.g. offset=100000) get slow?", options: ["The network is slower", "The database must scan and skip all preceding rows", "JSON gets larger", "Indexes are disabled"], answer: 1, diff: "intermediate", why: "OFFSET n still reads and discards n rows; at depth that's a near-full scan. Cursor pagination seeks via an index instead." },
    { code: "Page 1: items 1-20 returned.\nMeanwhile 5 new orders are inserted at the top.\nPage 2: offset=20, limit=20", q: "What bug can the user see with offset pagination here?", options: ["Nothing", "Duplicates — rows shifted down by the inserts, so page 2 repeats some of page 1", "A 500 error", "The pages reverse"], answer: 1, diff: "advanced", why: "Inserts shift offsets, so fixed offsets re-show or skip rows. Cursor pagination is stable under writes." },
    { q: "A cursor in cursor-based pagination is best thought of as…", options: ["A page number", "An opaque pointer to a position in a stable sort order", "A timestamp only", "The user's session id"], answer: 1, diff: "intermediate", why: "The cursor encodes where to resume in an indexed sort order; keeping it opaque lets you change the encoding later." },
    { q: "Cursor pagination needs which property of its sort key?", options: ["It must be random", "Stable and unique (e.g. createdAt + id tiebreaker)", "It must be the primary display field", "It must be mutable"], answer: 1, diff: "senior", why: "Equal sort values cause gaps/overlaps; a unique tiebreaker guarantees a total order to resume from." },
    { q: "Why always cap the page size server-side?", options: ["To save the client memory", "To prevent a client requesting limit=1000000 and exhausting server resources", "HTTP requires it", "To make caching work"], answer: 1, diff: "beginner", why: "Unbounded page sizes are a denial-of-service and memory risk; clamp limit to a sane max." }
  ]);

  add("idempotency", [
    { code: "POST /v1/orders\nIdempotency-Key: chk-1   (sent 3×; first two responses lost)", q: "With a correct idempotency implementation, how many orders exist and what does the 3rd call return?", options: ["3 orders; 201", "1 order; the stored response (200/201)", "0 orders; 409", "1 order; 500"], answer: 1, diff: "intermediate", why: "The key maps to one created order; repeats replay the stored response instead of creating more." },
    { q: "The classic race that breaks a naive idempotency check is…", options: ["Two different keys racing", "Two concurrent retries both passing an 'exists?' check then both inserting", "A slow database", "An expired token"], answer: 1, diff: "advanced", why: "Check-then-insert as two steps lets both retries create an order; insert the key atomically (unique constraint) first." },
    { q: "Why add a TTL to stored idempotency keys?", options: ["Security theater", "Keys can't be kept forever; a TTL bounds storage while covering the realistic retry window", "To make them faster", "HTTP requires it"], answer: 1, diff: "intermediate", why: "Retries happen within minutes/hours; a TTL reclaims storage while still catching duplicates in that window." },
    { q: "If the same Idempotency-Key arrives with a different request body, you should…", options: ["Process it as new", "Reject it (e.g. 422) — the key implies the same operation", "Ignore the body", "Return the old response silently"], answer: 1, diff: "senior", why: "A key reused with a different payload is a client bug or attack; rejecting avoids silently returning a mismatched result." },
    { q: "Which methods most need idempotency keys?", options: ["GET and HEAD", "Non-idempotent unsafe writes like POST (create)", "PUT and DELETE (already idempotent)", "OPTIONS"], answer: 1, diff: "beginner", why: "GET/PUT/DELETE are already idempotent by semantics; POST-create is the one that duplicates on retry." }
  ]);

  add("versioning", [
    { q: "Which change can ship in place on /v1 without a version bump?", options: ["Removing a field", "Renaming a field", "Adding a new optional response field", "Making an optional request field required"], answer: 2, diff: "beginner", why: "Additive, optional changes are backward compatible — clients ignore unknown fields. The others break existing clients." },
    { q: "Making a previously-optional REQUEST field required is…", options: ["Backward compatible", "Breaking — older clients that omit it now get 422", "Only breaking for responses", "Never breaking"], answer: 1, diff: "intermediate", why: "Existing senders don't include the field and start failing validation; that's a breaking change needing a new version." },
    { q: "The Sunset HTTP header is used to…", options: ["Enable caching", "Signal a deprecation/removal date for an endpoint or version", "Rate-limit", "Compress responses"], answer: 1, diff: "intermediate", why: "Sunset communicates when a resource will stop working, giving clients time to migrate." },
    { q: "Why retire an old version by usage metrics rather than a fixed calendar date?", options: ["Dates are illegal", "Old mobile app versions can't be force-upgraded; removing while they still call breaks real users", "Metrics are easier", "Calendars are unreliable"], answer: 1, diff: "senior", why: "You can't control when users update apps; drive removal by measured adoption + comms, not just a date." },
    { q: "A maintainable way to run v1 and v2 together is to…", options: ["Fork the entire codebase per version", "Keep one core domain model and version only the edge serializers/validators", "Only support one version at a time", "Put the version in a cookie"], answer: 1, diff: "advanced", why: "Versioning at the edge avoids duplicating business logic; both versions map to the same core with different shapes." }
  ]);

  add("error-design", [
    { code: "{ \"title\": \"Validation failed\", \"status\": 422, \"code\": \"INVALID_ORDER_ITEM\", \"requestId\": \"req-7f3a21\" }", q: "Why include a machine-readable `code` alongside the human `title`?", options: ["To make the body bigger", "So clients branch on a stable code instead of string-matching the title", "For encryption", "It's required by JSON"], answer: 1, diff: "intermediate", why: "Titles change with copy edits; a stable code lets clients handle errors programmatically without brittle string matching." },
    { q: "Why must a 500 response NOT include the raw exception/stack trace?", options: ["It's too long", "It leaks internals useful to attackers; log details server-side, return a generic message", "Clients can't read it", "It breaks JSON"], answer: 1, diff: "advanced", why: "Stack traces expose code paths, libraries, and sometimes secrets — keep them in logs, return a safe generic body." },
    { q: "The `requestId` in an error body exists mainly to…", options: ["Rate-limit the client", "Let support/engineers correlate the error with server logs/traces", "Encrypt the response", "Identify the user"], answer: 1, diff: "beginner", why: "A correlation id ties a customer's error to the exact request in your logs — essential for debugging." },
    { q: "RFC 9457 (Problem Details) recommends which content type for error bodies?", options: ["text/plain", "application/problem+json", "application/error", "application/xml"], answer: 1, diff: "senior", why: "Problem Details standardizes a JSON error shape under application/problem+json (type/title/status/detail/instance)." },
    { q: "A good validation error should…", options: ["Just say 'error'", "Name which field failed and why, with a stable code", "Return 200 with an error flag", "Include the SQL that failed"], answer: 1, diff: "intermediate", why: "Actionable errors point at the field and reason so the client can fix the request; never leak internals like SQL." }
  ]);

  add("architecture", [
    { q: "An API gateway's typical responsibilities are…", options: ["Running business logic", "Edge concerns: routing, auth, rate limiting, request ids (north-south)", "Storing the database", "Rendering HTML"], answer: 1, diff: "intermediate", why: "The gateway handles client→system edge cross-cutting concerns, forwarding to services that hold the logic." },
    { q: "North-south vs east-west traffic refers to…", options: ["Geography", "Client↔system (north-south) vs service↔service (east-west) communication", "Read vs write", "HTTP vs HTTPS"], answer: 1, diff: "advanced", why: "Gateways address north-south; a service mesh addresses east-west concerns like mTLS and retries between services." },
    { q: "Putting the payment provider call behind the service (not the client) is better because…", options: ["It's faster for the client", "The server controls secrets, retries, idempotency and reconciliation; the client shouldn't hold payment logic", "Clients can't make HTTPS calls", "It avoids CORS"], answer: 1, diff: "intermediate", why: "Sensitive, stateful, retry-careful work belongs server-side where you control secrets and consistency." },
    { q: "Why introduce a message broker/queue between services?", options: ["To make calls synchronous", "To decouple producers from consumers and absorb bursts, enabling async, independently-scaled processing", "To avoid using HTTP", "To store the primary data"], answer: 1, diff: "advanced", why: "Queues decouple timing and load; consumers process at their own pace and can be added/removed without touching producers." },
    { q: "A read replica primarily helps when…", options: ["Writes are the bottleneck", "Read load is high and can tolerate slight replication lag", "You need stronger consistency", "You want fewer servers"], answer: 1, diff: "senior", why: "Replicas scale reads but introduce lag — fine for browse/catalog, risky for read-after-write on critical paths." }
  ]);

  add("resilience", [
    { q: "A circuit breaker's job is to…", options: ["Encrypt traffic", "Stop sending requests to a failing dependency for a while, so it can recover and you fail fast", "Retry forever", "Cache responses"], answer: 1, diff: "intermediate", why: "Open circuit = fail fast and shed load off a struggling dependency, preventing resource exhaustion and giving it room to recover." },
    { q: "Why add jitter to retry backoff?", options: ["To slow clients deliberately", "To de-synchronize many clients so they don't all retry at the same instant (thundering herd)", "Encryption", "To honor Retry-After"], answer: 1, diff: "advanced", why: "Without jitter, synchronized retries hammer a recovering service in waves; randomization spreads them out." },
    { q: "A 'retry storm' happens when…", options: ["One client retries once", "Retries amplify load on an already-slow dependency, worsening the outage", "The server restarts", "A cache misses"], answer: 1, diff: "advanced", why: "Each retry adds in-flight load; during a slowdown this feedback loop can take the dependency fully down." },
    { q: "A timeout budget across a call chain should be…", options: ["The same at every layer", "Decreasing inward, so inner calls time out before the outer caller does", "Unlimited", "Only on the client"], answer: 1, diff: "senior", why: "If an outer timeout is 2s, inner calls must be shorter (e.g. 1.5s) to leave room to handle the failure, not just inherit it." },
    { q: "A bulkhead pattern protects you by…", options: ["Encrypting data", "Isolating resource pools so one failing dependency can't consume all threads/connections", "Caching aggressively", "Retrying more"], answer: 1, diff: "senior", why: "Separate pools per dependency mean a hung downstream exhausts only its bulkhead, not the whole service." }
  ]);

  add("protocols", [
    { q: "A key reason to choose gRPC for internal service-to-service calls is…", options: ["It works great in browsers", "Binary Protobuf + HTTP/2 + typed contracts give low latency and strong contracts", "It's human-readable", "It avoids schemas"], answer: 1, diff: "intermediate", why: "gRPC shines east-west: compact binary, multiplexed HTTP/2, codegen'd typed stubs. Browsers need gRPC-Web, a friction point." },
    { q: "The N+1 problem in GraphQL arises when…", options: ["Too many mutations run", "A resolver fires one query per item in a list instead of batching", "The schema is too small", "You use fragments"], answer: 1, diff: "advanced", why: "Resolving a list's nested field naively hits the DB once per element; DataLoader batches these into one query." },
    { q: "Compared to REST, GraphQL's main benefit for mobile is…", options: ["Simpler caching", "Clients request exactly the fields they need in one round trip, avoiding over/under-fetching", "Smaller server code", "No need for auth"], answer: 1, diff: "intermediate", why: "One flexible query composes many entities with precise fields — great for varied mobile screens; the cost is caching and query-cost control." },
    { q: "A risk GraphQL introduces that REST usually doesn't is…", options: ["Statelessness", "Expensive/deeply-nested queries acting as an accidental DoS without cost/depth limits", "JSON parsing", "Versioning"], answer: 1, diff: "senior", why: "A single crafted query can fan out enormously; you need query-cost analysis, depth limits, and persisted queries." },
    { q: "gRPC streaming is especially suited to…", options: ["One-off CRUD", "Continuous or bidirectional data flows (telemetry, chat, large transfers)", "Static file hosting", "Simple form posts"], answer: 1, diff: "advanced", why: "HTTP/2 streams let gRPC push server/client/bidirectional streams efficiently — overkill for simple request/response CRUD." }
  ]);

  add("realtime-protocols", [
    { q: "When is a webhook preferable to polling?", options: ["When you control both ends and want to avoid wasteful repeated requests", "When the provider is unreliable", "When you need a browser connection", "Never"], answer: 0, diff: "beginner", why: "Webhooks push on an event — timely and efficient vs polling's wasted empty requests. Add reconciliation if delivery is unreliable." },
    { q: "WebSockets are the right tool when…", options: ["You need request/response CRUD", "You need low-latency, bidirectional, persistent communication (live updates, chat)", "You want HTTP caching", "You need to upload a file"], answer: 1, diff: "intermediate", why: "A persistent duplex connection suits continuous two-way data; for simple request/response, plain HTTP is simpler." },
    { q: "A robust webhook CONSUMER must handle at-least-once delivery by…", options: ["Trusting each event once", "Deduping by event id and processing idempotently", "Polling instead", "Ignoring duplicates' ids"], answer: 1, diff: "advanced", why: "Providers retry on non-2xx, so the same event can arrive twice; dedupe by id and make handling idempotent." },
    { q: "A message queue gives you, versus direct sync calls…", options: ["Lower latency always", "Decoupling, buffering of bursts, and independent retry/scaling of consumers", "Stronger consistency", "Simpler code always"], answer: 1, diff: "intermediate", why: "Queues absorb spikes and decouple producer/consumer timing, at the cost of eventual consistency and more moving parts." },
    { q: "Why verify a webhook's signature AND timestamp?", options: ["Only for speed", "Signature proves authenticity; timestamp prevents replay of a captured valid payload", "To compress it", "To rate-limit"], answer: 1, diff: "senior", why: "HMAC verifies it came from the provider; a freshness window stops an attacker replaying an old, validly-signed event." }
  ]);

  add("protocol-matrix", [
    { q: "Public API consumed by many third parties in browsers → best default?", options: ["gRPC", "REST over HTTP/JSON", "Raw TCP", "GraphQL subscriptions"], answer: 1, diff: "beginner", why: "REST/JSON is universally supported, cacheable, and easy for external consumers; gRPC needs gRPC-Web and more tooling." },
    { q: "Dozens of internal services, latency-sensitive, typed contracts wanted → best fit?", options: ["REST/JSON", "gRPC", "Webhooks", "GraphQL"], answer: 1, diff: "intermediate", why: "Internal east-west traffic benefits from gRPC's binary efficiency, HTTP/2 multiplexing, and generated typed contracts." },
    { q: "A mobile client composing many entities per screen with varied needs → consider…", options: ["gRPC streaming", "GraphQL (with cost limits + DataLoader)", "SOAP", "Plain WebSockets"], answer: 1, diff: "intermediate", why: "GraphQL lets each screen fetch exactly what it needs in one trip; guard N+1 and query cost." },
    { q: "Reacting to a partner's payment events across the internet → best mechanism?", options: ["Long polling forever", "Signed webhooks with dedupe + reconciliation", "gRPC bidi stream to the partner", "A shared database"], answer: 1, diff: "advanced", why: "Event notification across trust boundaries fits webhooks; secure and dedupe them, with a reconciliation poll as backup." },
    { q: "The honest summary of 'which protocol' is…", options: ["gRPC is always best", "It depends on the consumer, latency needs, caching, and team/tooling — match protocol to context", "REST is obsolete", "GraphQL replaces everything"], answer: 1, diff: "senior", why: "There's no universal winner; senior engineers choose per consumer, performance, caching and ecosystem constraints." }
  ]);

  add("express-workshop", [
    { code: "app.post('/v1/orders', (req, res) => {\n  console.log(req.body.customerId); // undefined\n});", q: "Most likely cause that req.body is undefined?", options: ["The route is wrong", "Missing app.use(express.json()) before the route", "The client sent no body", "Express is broken"], answer: 1, diff: "beginner", why: "Express doesn't parse bodies by default; add express.json() before any route that reads req.body." },
    { code: "app.use('/v1', authenticate);\napp.get('/v1/orders', listOrders);\n// vs the reverse order", q: "Why does middleware order matter here?", options: ["It doesn't", "Middleware runs top-to-bottom; authenticate must be registered before the routes it should protect", "Routes always run first", "Express sorts them alphabetically"], answer: 1, diff: "intermediate", why: "Express executes middleware in registration order; put cross-cutting middleware before the routes it guards." },
    { q: "The Express error-handling middleware is identified by…", options: ["Its name", "Having four arguments (err, req, res, next)", "Being first", "A decorator"], answer: 1, diff: "advanced", why: "Express treats a 4-arg middleware as the error handler; register it last so thrown errors funnel into it." },
    { q: "Why validate input in middleware before the business logic?", options: ["To slow requests", "To reject bad input early (422) before touching the DB or external services", "To log more", "To cache"], answer: 1, diff: "intermediate", why: "Fail fast: validation up front saves work and prevents malformed data reaching your logic or storage." },
    { q: "For production, express.json({ limit: '100kb' }) helps by…", options: ["Speeding JSON parsing", "Capping body size to prevent memory-exhaustion from huge payloads", "Enabling compression", "Adding auth"], answer: 1, diff: "senior", why: "An unbounded body is a DoS vector; capping size rejects oversized payloads (413) before buffering them." }
  ]);

  add("testing-workbench", [
    { q: "A test that sends a request and asserts status + body shape is checking…", options: ["Performance", "The contract (what the API returns for given input)", "The database schema", "Network speed"], answer: 1, diff: "beginner", why: "Contract/behavior tests lock the externally-observable response for happy and error paths." },
    { q: "Why test error paths (401/403/422), not just the happy path?", options: ["To pad the suite", "Most production bugs live in edge/error handling; clients depend on correct error behavior", "It's required by HTTP", "To slow CI"], answer: 1, diff: "intermediate", why: "Error handling is where regressions hide; clients branch on these statuses, so they must stay stable." },
    { q: "Chaining requests (create → fetch created id) in a test suite verifies…", options: ["Only the first call", "That resources created by the API are actually retrievable/consistent", "Network latency", "The UI"], answer: 1, diff: "intermediate", why: "End-to-end flows catch integration bugs a single-endpoint test misses, e.g. a create that doesn't persist." },
    { q: "A deterministic test environment matters because…", options: ["It's faster", "Flaky, non-deterministic tests erode trust and hide real regressions", "It uses less memory", "HTTP requires it"], answer: 1, diff: "advanced", why: "Determinism is what makes a failing test meaningful; flakiness trains teams to ignore red builds." },
    { q: "Injecting a failure (e.g. force a 500) in a test verifies…", options: ["Nothing useful", "That your error handling and client behave correctly when things break", "Only logging", "The CDN"], answer: 1, diff: "intermediate", why: "Fault injection proves resilience paths work — you can't verify recovery you never trigger." }
  ]);

  add("testing-challenges", [
    { code: "POST /v1/orders  → 400 Bad Request\nBody was copied from a JS object literal.", q: "Most likely cause of the 400?", options: ["Wrong auth", "The body isn't valid JSON (single quotes / trailing comma)", "Rate limited", "Server down"], answer: 1, diff: "beginner", why: "400 = the server couldn't parse the request; JS-style object text (single quotes, trailing commas) isn't valid JSON." },
    { q: "All /v1/* calls return 401 though you send a token. First thing to check?", options: ["The database", "That the Authorization header is present and in 'Bearer <token>' form, and the token isn't expired", "The response body", "The CDN cache"], answer: 1, diff: "intermediate", why: "401 is unauthenticated: verify the header reaches the server, the scheme is right, and the token is valid/unexpired." },
    { q: "One endpoint returns 403 with a valid token that works elsewhere. Likely cause?", options: ["Expired token", "Missing scope or accessing another user's resource (authorization, not authentication)", "Bad JSON", "Server crash"], answer: 1, diff: "intermediate", why: "403 = authenticated but not permitted; the token lacks the needed scope or ownership for that specific resource." },
    { code: "Checkout intermittently returns 504 during payment-provider slowness.", q: "Best first mitigation?", options: ["Raise the timeout to 60s", "Add a timeout + circuit breaker and mark affected orders PENDING, then reconcile", "Retry the charge immediately", "Ignore it"], answer: 1, diff: "advanced", why: "504 = upstream timeout; fail fast with a breaker and resolve the uncertain charge via reconciliation, don't blind-retry." },
    { q: "A partner's integration suddenly gets 429s during a sale. Correct response?", options: ["Remove all rate limits", "Honor Retry-After + backoff; consider a per-partner quota/burst bump", "Switch them to GET", "Block the partner"], answer: 1, diff: "intermediate", why: "429 = slow down; the client should back off, and you can isolate/raise that partner's quota without weakening global limits." }
  ]);

  add("openapi-studio", [
    { q: "The main benefit of a single OpenAPI spec is…", options: ["Faster servers", "One machine-readable contract driving docs, SDKs, server stubs, and contract tests", "Smaller payloads", "No need for versioning"], answer: 1, diff: "beginner", why: "The spec is the source of truth a whole toolchain consumes, keeping docs and clients in sync with the contract." },
    { code: "paths:\n  /v1/orders/{orderId}:\n    get:\n      parameters:\n        - in: path\n          name: id", q: "What's wrong with this path parameter?", options: ["Nothing", "The param name (id) must match the template {orderId}, and path params must be required:true", "GET can't have parameters", "It needs a body"], answer: 1, diff: "intermediate", why: "A {template} needs a matching in:path parameter of the same name, and path params are always required." },
    { q: "Contract tests derived from the spec catch which problem best?", options: ["Slow queries", "A server change that breaks the published contract, before it reaches clients", "Memory leaks", "CSS bugs"], answer: 1, diff: "advanced", why: "Replaying the spec against the running API fails CI when the implementation drifts from the contract." },
    { q: "Adding a new optional field to a response schema is…", options: ["A breaking change", "Backward compatible — existing clients ignore it", "Invalid OpenAPI", "Only allowed in v2"], answer: 1, diff: "intermediate", why: "Optional additive fields don't break conforming clients; removing or renaming fields does." },
    { q: "A duplicate operationId across two operations is a problem because…", options: ["It's prettier", "Code generators turn operationIds into unique method names; duplicates collide", "It slows the server", "It breaks TLS"], answer: 1, diff: "senior", why: "operationId must be unique document-wide; SDK generators map it to function names, so duplicates break codegen." }
  ]);

  add("security", [
    { q: "BOLA / IDOR (broken object-level authorization) is when…", options: ["Passwords are weak", "An authenticated user can access another user's object by changing an id, with no ownership check", "TLS is misconfigured", "Tokens expire too fast"], answer: 1, diff: "advanced", why: "OWASP API #1: authentication isn't enough — every object access must verify the caller owns/may access that specific object." },
    { q: "Why recompute an order's price server-side instead of trusting the client?", options: ["Speed", "A malicious client would send a $0 price; the server must be the source of truth for money", "To save bandwidth", "JSON requires it"], answer: 1, diff: "beginner", why: "Any client-controlled value is attacker-controlled; never trust price, totals, roles, or ownership from the client." },
    { q: "Parameterized queries prevent SQL injection by…", options: ["Encrypting the query", "Sending values separately from the SQL so input can't alter the query structure", "Hiding the database", "Rate limiting"], answer: 1, diff: "intermediate", why: "Placeholders ($1, $2) keep data as data; string-concatenating user input lets it change the query — the injection." },
    { code: "GET /v1/orders/ORD-10025\nAuthorization: Bearer <valid token for a DIFFERENT customer>", q: "What must the endpoint do before returning the order?", options: ["Nothing — the token is valid", "Check that the order belongs to the authenticated customer (ownership)", "Rate limit", "Cache it"], answer: 1, diff: "advanced", why: "A valid token proves identity, not authorization for this object; without an ownership check this is a BOLA vulnerability." },
    { q: "Secrets like API keys should be…", options: ["Hard-coded for speed", "Stored outside code (env/secret manager), rotated, and never logged", "Emailed to partners", "Put in the URL"], answer: 1, diff: "senior", why: "Secrets in code or logs leak; keep them in a secret store, rotate them, and keep them out of URLs and logs." }
  ]);

  add("oauth", [
    { q: "In OAuth2, the access token's job is to…", options: ["Identify the end user to other users", "Authorize the client to call resources on the user's behalf, carrying scopes", "Encrypt the connection", "Replace HTTPS"], answer: 1, diff: "intermediate", why: "The access token represents delegated authorization (what the client may do), scoped and short-lived." },
    { q: "OIDC adds what on top of OAuth2?", options: ["Rate limiting", "An identity layer: the ID token (who the user is) via standardized claims", "Caching", "Compression"], answer: 1, diff: "intermediate", why: "OAuth2 is authorization; OIDC layers authentication, issuing an ID token with identity claims." },
    { code: "header.payload.signature  (a JWT)\n// payload base64url-decodes to readable JSON", q: "What does it mean that a JWT's payload is only base64url-encoded, not encrypted?", options: ["It's secret", "Anyone can read the claims; never put secrets in it — integrity comes from the signature, not confidentiality", "It's invalid", "It's compressed"], answer: 1, diff: "advanced", why: "A standard JWT is signed, not encrypted: the payload is readable by anyone. The signature prevents tampering, not reading." },
    { q: "The hard part of JWTs compared to opaque tokens is…", options: ["They're slower to read", "Revocation before expiry — they're self-contained, so you need short expiry or a denylist", "They can't carry claims", "They need a database"], answer: 1, diff: "senior", why: "JWTs avoid a per-call lookup but can't be easily revoked; opaque tokens revoke instantly but require introspection." },
    { q: "Short-lived access tokens + refresh tokens exist to…", options: ["Slow the client", "Limit the damage window of a leaked access token while avoiding frequent re-login", "Replace scopes", "Encrypt traffic"], answer: 1, diff: "intermediate", why: "A short access-token lifetime bounds exposure; the refresh token quietly gets a new one without user friction." }
  ]);

  add("rate-limiting", [
    { q: "Why key rate limits by authenticated identity rather than IP?", options: ["IPs are faster", "IPs are shared (NAT) and spoofable; per-key limits are fair and precise", "IPs change the status code", "It's required by HTTP"], answer: 1, diff: "intermediate", why: "Many users share an IP and attackers rotate them; per-customer/partner keys isolate callers fairly." },
    { q: "Token bucket vs leaky bucket: token bucket is chosen when you want to…", options: ["Force perfectly smooth output", "Allow short bursts up to the bucket size while bounding the sustained rate", "Never allow bursts", "Avoid any limit"], answer: 1, diff: "advanced", why: "Token bucket permits bursts (accumulated tokens) with a bounded refill rate; leaky bucket enforces smooth constant output." },
    { code: "HTTP/1.1 429 Too Many Requests\nRetry-After: 30", q: "What should a well-behaved client do?", options: ["Retry immediately in a loop", "Wait ~30s (honor Retry-After) then retry with backoff", "Give up forever", "Switch to POST"], answer: 1, diff: "beginner", why: "429 means slow down; honoring Retry-After plus exponential backoff + jitter is the correct client behavior." },
    { q: "In a multi-node deployment, correct global rate limiting needs…", options: ["Each node to count locally", "A shared store with atomic increments so all nodes see one consistent count", "No coordination", "A bigger database"], answer: 1, diff: "senior", why: "Per-node local counters let a client exceed N× the limit; a shared atomic counter (e.g. Redis) enforces the real limit." },
    { q: "A fixed-window limiter's classic weakness is…", options: ["It's too strict", "Burst at the window boundary — 2× the limit across the seam between windows", "It needs HTTPS", "It can't return 429"], answer: 1, diff: "advanced", why: "A client can send a full window at the end of one window and another at the start of the next; sliding windows smooth this." }
  ]);

  add("performance", [
    { q: "Why report p95/p99 latency instead of the mean?", options: ["Means are illegal", "The mean hides the slow tail that users actually feel", "p99 is easier to compute", "They're identical"], answer: 1, diff: "intermediate", why: "A good average can mask a terrible tail; p95/p99 reflect the worst experiences real users hit." },
    { code: "A page makes 20 parallel API calls.\n1% of calls take 2s (the rest are fast).", q: "Roughly what fraction of page loads have at least one slow call?", options: ["1%", "About 18% (1 - 0.99^20)", "0%", "100%"], answer: 1, diff: "senior", why: "Tail latency amplifies under fan-out: 1-0.99^20 ≈ 0.18, so ~18% of pages feel the 2s call. The tail dominates perceived speed." },
    { q: "Little's Law (L = λ × W) lets you estimate…", options: ["Disk size", "Concurrent in-flight requests from arrival rate × service time, to size pools", "Cache hit rate", "Error budget"], answer: 1, diff: "advanced", why: "At 200 req/s × 0.05s, ~10 requests are in flight; it sizes thread/connection pools so you don't queue and collapse." },
    { q: "An under-sized connection pool under load causes…", options: ["Lower latency", "Queueing that blows up latency and causes timeouts", "Fewer errors", "More cache hits"], answer: 1, diff: "intermediate", why: "When concurrency exceeds the pool, requests queue; wait time compounds into latency spikes and timeouts." },
    { q: "Before caching a slow endpoint, you should first…", options: ["Always cache immediately", "Find the real cause (missing index, N+1) — caching a bug just hides it", "Add more servers", "Remove validation"], answer: 1, diff: "senior", why: "A cache over a fixable query masks a latent problem and adds consistency risk; fix the root cause first." }
  ]);

  add("caching", [
    { code: "Cache-Control: private, max-age=0, no-store", q: "What does this say about caching a personalized response?", options: ["Cache it at the CDN", "Don't store it — it's private/personalized and must not be shared-cached", "Cache for 1 hour", "Compress it"], answer: 1, diff: "intermediate", why: "private/no-store keeps personalized or sensitive responses out of shared caches to avoid leaking one user's data to another." },
    { q: "An ETag + If-None-Match exchange saves bandwidth by…", options: ["Compressing the body", "Returning 304 when unchanged, so the client reuses its cache instead of re-downloading", "Skipping auth", "Avoiding DNS"], answer: 1, diff: "intermediate", why: "The validator lets the server say 'not modified' (304) cheaply, avoiding resending an unchanged body." },
    { q: "The genuinely hard part of caching is usually…", options: ["Reading the cache", "Invalidation — knowing when cached data is stale and refreshing it", "Setting a TTL", "Choosing a port"], answer: 1, diff: "advanced", why: "'There are only two hard things…': deciding when cached data is no longer valid is the core difficulty." },
    { q: "Caching volatile inventory with a long TTL leads to…", options: ["Faster checkout only", "Stale reads — customers order out-of-stock items (overselling)", "Stronger consistency", "Lower memory use"], answer: 1, diff: "advanced", why: "Volatile data needs short TTL or event-based invalidation; otherwise the cache shows stock that's already gone." },
    { q: "Why can't you cache a response with Cache-Control: no-store at the CDN?", options: ["It's too big", "no-store forbids storing the response anywhere", "It's encrypted", "It has no ETag"], answer: 1, diff: "beginner", why: "no-store explicitly forbids any cache from keeping a copy — used for sensitive or always-fresh data." }
  ]);

  add("observability", [
    { q: "The 'three pillars' of observability are…", options: ["CPU, memory, disk", "Logs, metrics, and traces", "Dev, staging, prod", "Auth, authz, audit"], answer: 1, diff: "beginner", why: "Logs (events), metrics (aggregates/time-series), and traces (request paths across services) together explain system behavior." },
    { q: "A distributed trace is most useful for…", options: ["Counting total requests", "Following one request across services to find the slow or failing span", "Storing user data", "Rate limiting"], answer: 1, diff: "intermediate", why: "Traces localize where latency/errors occur in a multi-service call path — the 'where' that logs alone struggle to show." },
    { q: "A correlation/request id should be…", options: ["Generated fresh at every service", "Created at the edge and propagated through all services + logs", "Secret", "The user's password"], answer: 1, diff: "intermediate", why: "One id carried end-to-end ties all logs/spans of a request together; regenerating it per service breaks correlation." },
    { q: "An SLO is best described as…", options: ["A hard contract with penalties", "A target for a reliability metric (e.g. 99.9% availability) that guides an error budget", "A log format", "A load test"], answer: 1, diff: "advanced", why: "SLOs set target levels (availability, latency, error rate); the gap to 100% is the error budget guiding release risk." },
    { q: "Alerting on symptoms (e.g. checkout error rate) rather than causes (e.g. CPU) is better because…", options: ["CPU is hard to measure", "Symptom alerts catch user-impacting problems regardless of the underlying cause", "It's cheaper", "Causes never matter"], answer: 1, diff: "senior", why: "Cause-based alerts miss novel failures; alerting on user-facing symptoms catches what actually hurts, then you diagnose the cause." }
  ]);

  add("business-scenario", [
    { q: "Why does ShopSphere need a stable API contract for its mobile app specifically?", options: ["Phones are slow", "Old app versions can't be force-upgraded, so breaking the contract strands users", "Mobile can't use JSON", "To save battery"], answer: 1, diff: "intermediate", why: "You don't control when users update apps; a breaking change breaks everyone still on the old version." },
    { q: "The payments team needs 'exactly-once payment effects despite flaky networks.' This maps to which API concept?", options: ["Pagination", "Idempotency (keys + reconciliation)", "Caching", "Compression"], answer: 1, diff: "intermediate", why: "Safe-under-retry money movement is exactly idempotency plus reconciliation of uncertain outcomes." },
    { q: "Platform ops asking for 'traces, metrics, SLOs' is really asking for…", options: ["More servers", "Observability so they can operate and debug in production", "A new language", "A bigger cache"], answer: 1, diff: "beginner", why: "Running a system in production without observability means long, blind outages; it's a first-class requirement." },
    { q: "A customer being double-charged during a flash sale most threatens which business asset?", options: ["Disk space", "Trust (and refund/support cost)", "CDN bandwidth", "Code size"], answer: 1, diff: "intermediate", why: "Money bugs erode customer trust and generate refunds + support load — the kind of failure idempotency exists to prevent." },
    { q: "Connecting a technical choice (e.g. a cache TTL) to a business outcome (overselling) is a hallmark of…", options: ["Junior work", "Senior engineering judgment", "Marketing", "QA only"], answer: 1, diff: "senior", why: "Seniors reason about business impact, not just mechanisms — a TTL decision is really an overselling-risk decision." }
  ]);

  add("senior-decisions", [
    { q: "The honest answer to most senior design questions is…", options: ["Always use the newest tech", "'It depends' — on load, consistency needs, team, and constraints; then justify the trade-off", "Always microservices", "Always cache"], answer: 1, diff: "intermediate", why: "Seniority shows in naming the trade-off and the conditions that flip the decision, not in a one-size answer." },
    { q: "When does REST beat GraphQL?", options: ["Never", "Simple CRUD with strong HTTP/CDN caching needs and many external consumers", "Only internally", "When you dislike JSON"], answer: 1, diff: "advanced", why: "REST's uniform caching and ubiquity win for straightforward, cache-heavy, widely-consumed APIs; GraphQL wins for flexible composition." },
    { q: "A distributed transaction across order, payment, and inventory services is usually replaced by…", options: ["A bigger database lock", "A saga: local transactions + compensating actions", "Ignoring failures", "A cache"], answer: 1, diff: "advanced", why: "You can't hold one ACID transaction across services/externals; a saga sequences local commits with compensations." },
    { q: "When is a synchronous external call acceptable instead of async + reconcile?", options: ["Always", "When the dependency is fast and highly reliable and a bounded timeout is tolerable", "Never", "Only for payments"], answer: 1, diff: "senior", why: "Async shines for slow/flaky externals; a fast, reliable internal call with a timeout can stay synchronous for simplicity." },
    { q: "Choosing a modular monolith over microservices for a new small team reflects…", options: ["Fear of new tech", "Matching architecture to current scale/team, extracting services only when needed", "Laziness", "A lack of ambition"], answer: 1, diff: "intermediate", why: "Premature microservices add distributed-systems cost before you need it; start modular, split on real pressure." }
  ]);

  add("incidents", [
    { q: "The first priority during an active production incident is usually…", options: ["Write a full root-cause analysis", "Stop the bleeding (roll back / breaker / shed load), then diagnose", "Blame the last committer", "Rewrite the service"], answer: 1, diff: "intermediate", why: "Mitigate user impact first (often a rollback), then do root-cause analysis once things are stable." },
    { q: "Duplicate orders correlated with poor mobile connectivity point to…", options: ["A database bug", "Client retries on a non-idempotent POST with no idempotency key", "A CDN misconfig", "Expired tokens"], answer: 1, diff: "intermediate", why: "Lost responses trigger retries; without idempotency keys each retry creates another order." },
    { q: "A post-incident review's main goal is…", options: ["Assign blame", "Find systemic fixes (tests, alerts, runbooks) so it can't recur — blameless", "Punish the on-call", "Close the ticket fast"], answer: 1, diff: "advanced", why: "Blameless retrospectives surface process/system gaps; blame hides information and repeats failures." },
    { q: "A webhook delivered multiple times double-marked orders paid. The durable fix is…", options: ["Ask the provider to stop", "An event-id dedupe store + idempotent processing", "Polling instead", "Turning off webhooks"], answer: 1, diff: "advanced", why: "At-least-once delivery is the contract; dedupe by event id and process idempotently on your side." },
    { q: "A customer seeing another customer's order by changing the id is which class of bug?", options: ["Caching", "Broken object-level authorization (BOLA/IDOR) — high severity", "Rate limiting", "Serialization"], answer: 1, diff: "senior", why: "Missing ownership checks expose data; it's a top OWASP API risk and warrants immediate patch + audit." }
  ]);

  add("challenges", [
    { q: "To cancel an order at /v1/orders/{id}, the cleanest choice is…", options: ["GET /v1/orders/{id}/cancel", "DELETE /v1/orders/{id} or PATCH status=CANCELLED", "POST /v1/cancelOrder", "PUT /v1/orders/{id}"], answer: 1, diff: "beginner", why: "The method carries intent; cancellation is a DELETE or a status PATCH, never a GET (which must be safe)." },
    { q: "Given { \"data\": [...], \"pagination\": { \"total\": 128 } }, the item count lives in…", options: ["data.length only", "pagination.total (128); the items are in data[]", "A header", "The URL"], answer: 1, diff: "beginner", why: "Separating payload (data) from metadata (pagination) is the point; the total count is metadata." },
    { q: "Two buyers race for the last unit in stock. The correct approach is…", options: ["First to click wins by luck", "An atomic conditional reserve (row lock / conditional update / unique constraint); the loser gets 409", "Cache the stock", "Retry both"], answer: 1, diff: "advanced", why: "Make the reservation the atomic point of truth so exactly one succeeds; the other gets a conflict." },
    { q: "You must add richer pricing to the order response without breaking clients. Do…", options: ["Rename total to price", "Add new optional fields additively; keep existing fields", "Remove the old fields", "Switch to /v2 immediately"], answer: 1, diff: "intermediate", why: "Additive optional fields are backward compatible; only removals/renames force a version bump." },
    { q: "A charge times out and you don't know if it succeeded. Correct move?", options: ["Retry the charge immediately", "Reconcile via webhook/status lookup; resolve the state machine — never blind-retry", "Mark it failed at once", "Charge again to be safe"], answer: 1, diff: "senior", why: "Uncertain external outcomes demand reconciliation, not blind retries that risk double charges." }
  ]);

  add("interview-prep", [
    { q: "A strong senior answer to 'explain X' usually follows roughly which shape?", options: ["Define only", "Define → how it works → business use → trade-offs → failure mode → mitigation", "Just name tools", "Memorized definition"], answer: 1, diff: "intermediate", why: "Depth and structure distinguish senior answers: mechanism, trade-offs, and failure handling, not just a definition." },
    { q: "When an interviewer keeps asking 'and then what breaks?', they're testing…", options: ["Memorization", "Whether you understand failure modes and operate systems, not just build them", "Typing speed", "Tool trivia"], answer: 1, diff: "intermediate", why: "Follow-up drilling probes real depth: can you reason about how your design fails and how you'd handle it?" },
    { q: "For a behavioral 'tell me about an incident' question, the weakest answer…", options: ["Quantifies impact and names a systemic fix", "Has no measurable impact and ends at 'I restarted it'", "Uses the STAR structure", "Describes mitigate-then-diagnose"], answer: 1, diff: "intermediate", why: "Strong answers quantify impact and close with a preventive fix; 'rebooted and hoped' signals no systems thinking." },
    { q: "Asked to design an API in an interview, a good first move is to…", options: ["Start coding immediately", "Clarify requirements/scale/consumers before drawing endpoints", "Pick a database", "Name a framework"], answer: 1, diff: "advanced", why: "Senior design starts by scoping constraints (consumers, scale, consistency) so the design is justified, not assumed." },
    { q: "The difference between a mid and senior answer to 'how do you secure an API?' is usually…", options: ["Senior lists more tools", "Senior names object-level authorization (BOLA), service identity, secrets handling, and business risk — not just 'add auth + HTTPS'", "Senior talks faster", "There is none"], answer: 1, diff: "senior", why: "Seniors go past authn/HTTPS to the failure that actually bites (BOLA), plus service-to-service identity and business framing." }
  ]);
})();
